      { label: "M156 6.2L V8 AMG Engine Core", x: 0, y: 0.04, z: 0.35, critical: true, details: "Main engine-bay area. Listen intensely for cold-start valvetrain tapping (lifter wear) and cam adjuster rattle. Verify if head bolts have been upgraded." },
      { label: "Firewall and Rear Engine Bay", x: 0, y: 0.05, z: 0.21, critical: true, details: "Rear section of the engine bay. Inspect for oil leaking from the massive magnesium valve covers onto the exhaust manifolds." },
      { label: "Right Rear Suspension and Subframe", x: -0.18, y: -0.08, z: -0.28, critical: false, details: "Important inspection point for suspension mounts, rear subframe condition, and differential mounts which suffer from the 630 Nm torque." },
      { label: "Left Rear Suspension and Subframe", x: 0.18, y: -0.08, z: -0.28, critical: false, details: "Rear suspension wear, subframe-area corrosion, and stability-related issues can show up here." },
      { label: "Exhaust and Rear Muffler", x: -0.1, y: -0.08, z: -0.5, critical: false, details: "Inspect the AMG quad-exhaust system. Often modified with secondary cat or resonator deletes for louder V8 sound." }
