      { label: "M273 5.5L V8 Engine Core", x: 0, y: 0.04, z: 0.35, critical: true, details: "CRITICAL: Listen for timing chain rattle (idler gear issue). Inspect the front of the engine for oil leaks from the 4 camshaft magnets." },
      { label: "Firewall, Rear Engine Bay & Intake", x: 0, y: 0.05, z: 0.21, critical: true, details: "Inspect the variable intake manifold mechanism at the front/center for broken plastic actuator levers." },
      { label: "Right Rear Suspension and Subframe", x: -0.18, y: -0.08, z: -0.28, critical: false, details: "Inner area ahead of the right rear wheel. Important inspection point for suspension mounts, rear subframe condition, and rust." },
      { label: "Left Rear Suspension and Subframe", x: 0.18, y: -0.08, z: -0.28, critical: false, details: "Rear suspension wear, subframe-area corrosion, and stability-related issues can show up here." },
      { label: "Exhaust and Rear Muffler", x: -0.1, y: -0.08, z: -0.5, critical: false, details: "Area around the rear section of the exhaust. Useful for checking the catalytic converters and muffler." }
